@startuml

class Gym {
  + ComputeMonthlyBalance(month: int, year: int): double
  + ComputeYearlyBalance(year: int): double
  + SendArrearsReminder(): void
  + SendMedicalCheckReminder(): void
}

class Customer {
  + Name : string
  + Surname : string
  + Age : int
  + Address : string
  + Profession : string
}

class Subscription {
  + Type : string
}

class AdditionalService {
  + Name : string
}

class WorkoutPlan {
  + Exercises : string
  + Repetitions : int
  + Frequency : int
}

class MedicalStaff {
  + Name : string
}

class MedicalCheck {
  + Weight : float
  + BodyFat : float
  + Electrocardiogram : string
  + RestingHeartbeats : int
  + StressHeartbeats : int
}

Gym "1" -- "*" Customer
Gym "1" -- "*" MedicalStaff
Customer "1" -- "0..1" Subscription
Customer "1" -- "0..*" AdditionalService
Customer "1" -- "0..1" WorkoutPlan
Customer "1" -- "0..*" MedicalCheck
MedicalStaff "1" -- "*" MedicalCheck

@enduml

